<script setup>
import { computed,ref } from 'vue';import { storeToRefs } from 'pinia';import { useNpwStore } from '@/stores/npw';import { useWaferColorScale } from '@/composables/useWaferColorScale';import { useWafer3DSync } from '@/composables/useWafer3DSync';import NpwFilter from '@/components/NpwFilter.vue';import WaferSidePanel from './WaferSidePanel.vue';import WaferMeasurementTable from './WaferMeasurementTable.vue';import WaferTrendCharts from './WaferTrendCharts.vue'
const store=useNpwStore();const {filteredRows,filterVersion}=storeToRefs(store);const sideMode=ref('BOTH');const selectedKey=ref('');const groupKey=r=>`${r.time}|${r.eqpid}|${r.chid}|${r.ppid}|${r.foupid}`;const groups=computed(()=>{const map=new Map();filteredRows.value.forEach(r=>{const k=groupKey(r);if(!map.has(k))map.set(k,{});map.get(k)[r.side]=r});return map});const current=computed(()=>groups.value.get(selectedKey.value)||[...groups.value.values()].find(x=>x['1']&&x['2'])||[...groups.value.values()][0]||{});const activeKey=computed(()=>groups.value.has(selectedKey.value)?selectedKey.value:([...groups.value.entries()].find(([,v])=>v===current.value)?.[0]||''));const selectRow=row=>{selectedKey.value=groupKey(row)};const s1=computed(()=>current.value['1']);const s2=computed(()=>current.value['2']);const side1Scale=useWaferColorScale(s1);const side2Scale=useWaferColorScale(s2);const scale=s=>s==='1'?side1Scale:side2Scale;const {sync,view,update,reset,top}=useWafer3DSync();const shown=computed(()=>['1','2'].filter(s=>sideMode.value==='BOTH'||sideMode.value===`SIDE ${s}`));const tableRows=computed(()=>filteredRows.value);
</script><template><div class="layout"><NpwFilter/><main :key="filterVersion"><section class="wafer-zone" :class="{single:shown.length===1}"><WaferSidePanel v-for="s in shown" :key="s" :side="s" :row="s==='1'?s1:s2" :min="scale(s).min.value" :max="scale(s).max.value" :view="view" :colors="scale(s).colors" :sync="sync" show-scale @view-change="update" @reset="reset" @top="top" @toggle-sync="sync=$event"/></section><WaferTrendCharts :rows="filteredRows" :selected-key="activeKey" @select="selectedKey=$event"/><WaferMeasurementTable :rows="tableRows" :selected-key="activeKey" @select="selectRow"/></main></div></template>
<style scoped>.layout{display:grid;gap:16px}.layout>main{display:grid;min-width:0;gap:16px;animation:filterApply .42s ease-out}.wafer-zone{display:grid;grid-template-columns:1fr 1fr;background:#fff;border:1px solid #dfe5eb;border-radius:12px;box-shadow:0 5px 18px rgba(35,55,75,.07);overflow:hidden}.wafer-zone>article:first-child{border-right:1px solid #e2e7ed}.wafer-zone.single{grid-template-columns:1fr}.wafer-zone.single>article{border-right:0}@keyframes filterApply{from{opacity:.35;transform:translateY(8px)}to{opacity:1;transform:none}}@media(max-width:1200px){.wafer-zone{grid-template-columns:1fr}.wafer-zone>article:first-child{border-right:0;border-bottom:1px solid #e2e7ed}}</style>
